  function isNumericInputField(target) {
    if (!target || target.tagName !== "INPUT") {
      return false;
    }
    if (target.id === "ledgerCategoryInput") {
      return false;
    }
    if (target.type === "number" || target.getAttribute("inputmode") === "numeric") {
      return true;
    }
    if (["search", "date", "file", "password", "email"].includes(target.type)) {
      return false;
    }
    const numericIdentity = [
      target.id,
      target.name,
      target.className,
      target.getAttribute("placeholder"),
      target.getAttribute("aria-label")
    ].join(" ");
    if (/search/i.test(numericIdentity)) {
      return false;
    }
    return /(phone|mobile|income|amount|salary|deposit)/i.test(numericIdentity);
  }

  function isDecimalNumericField(input) {
    const step = String(input.getAttribute("step") || "");
    return input.type === "number" && (step === "any" || step.includes("."));
  }

  function isPhoneNumericField(input) {
    const numericIdentity = [
      input.id,
      input.name,
      input.className,
      input.getAttribute("placeholder"),
      input.getAttribute("aria-label")
    ].join(" ");
    return /(phone|mobile)/i.test(numericIdentity);
  }

  function cleanNumericInputValue(input) {
    if (!isNumericInputField(input)) {
      return;
    }
    const allowDecimal = isDecimalNumericField(input);
    const allowPhonePlus = isPhoneNumericField(input);
    let value = String(input.value || "");
    if (allowDecimal) {
      value = value.replace(/[^\d.]/g, "");
      const parts = value.split(".");
      value = parts.shift() + (parts.length ? `.${parts.join("")}` : "");
    } else if (allowPhonePlus) {
      const hasLeadingPlus = value.trim().startsWith("+");
      value = value.replace(/\D/g, "");
      value = hasLeadingPlus ? `+${value}` : value;
    } else {
      value = value.replace(/\D/g, "");
    }
    if (input.value !== value) {
      input.value = value;
    }
  }

  function installNumericInputGuards() {
    document.addEventListener("keydown", function (event) {
      const input = event.target;
      if (!isNumericInputField(input)) {
        return;
      }
      if (event.ctrlKey || event.metaKey || event.altKey) {
        return;
      }
      const allowedControlKeys = ["Backspace", "Delete", "Tab", "Enter", "Escape", "ArrowLeft", "ArrowRight", "ArrowUp", "ArrowDown", "Home", "End"];
      if (allowedControlKeys.includes(event.key)) {
        return;
      }
      if (/^\d$/.test(event.key)) {
        return;
      }
      if (event.key === "+" && isPhoneNumericField(input) && input.selectionStart === 0 && !String(input.value || "").includes("+")) {
        return;
      }
      if (event.key === "." && isDecimalNumericField(input) && !String(input.value || "").includes(".")) {
        return;
      }
      event.preventDefault();
    });

    document.addEventListener("input", function (event) {
      cleanNumericInputValue(event.target);
    });
  }

  installNumericInputGuards();

  function ensureAppMessageBox() {
    if (appMessageOverlay) {
      return;
    }
    appMessageOverlay = document.createElement("div");
    appMessageOverlay.className = "app-message-overlay";
    appMessageOverlay.hidden = true;
    appMessageOverlay.innerHTML = `
      <section class="app-message-box" role="alertdialog" aria-modal="true" aria-labelledby="appMessageTitle">
        <div class="app-message-box__header">
          <h3 class="app-message-box__title" id="appMessageTitle">Message</h3>
          <button class="app-message-box__close" type="button" id="appMessageCloseBtn">Close</button>
        </div>
        <div class="app-message-box__body">
          <p class="app-message-box__text" id="appMessageText"></p>
        </div>
      </section>
    `;
    document.body.appendChild(appMessageOverlay);
    appMessageBox = appMessageOverlay.querySelector(".app-message-box");
    appMessageTitle = appMessageOverlay.querySelector("#appMessageTitle");
    appMessageText = appMessageOverlay.querySelector("#appMessageText");
    const closeButton = appMessageOverlay.querySelector("#appMessageCloseBtn");
    closeButton.addEventListener("click", function () {
      appMessageOverlay.hidden = true;
    });
    appMessageOverlay.addEventListener("click", function (event) {
      if (event.target === appMessageOverlay) {
        appMessageOverlay.hidden = true;
      }
    });
  }

  /**
   * Shows a branded confirmation dialog
   * @param {string} title 
   * @param {string} detail 
   * @param {string} tone - 'error', 'success', 'warning', 'info'
   * @returns {Promise<boolean>}
   */
  function openAppConfirm(title, detail, tone) {
    return new Promise(function (resolve) {
      const overlay = document.createElement("div");
      overlay.className = "app-message-overlay";
      overlay.style.zIndex = "10002";
      overlay.style.display = "flex";
      overlay.style.alignItems = "center";
      overlay.style.justifyContent = "center";
      
      overlay.innerHTML = `
        <section class="app-message-box ${tone ? "app-message-box--" + tone : ""}" role="alertdialog" aria-modal="true" style="max-width:400px;margin:auto;">
          <div class="app-message-box__header">
            <h3 class="app-message-box__title">${escapeHtml(title || "Confirm Action")}</h3>
          </div>
          <div class="app-message-box__body" style="padding:20px;">
            <p class="app-message-box__text" style="margin:0;color:#5a6d8a;line-height:1.5;">${escapeHtml(detail || "Are you sure you want to proceed?")}</p>
          </div>
          <div class="app-message-box__footer" style="display:flex;gap:12px;padding:15px;justify-content:flex-end;border-top:1px solid #e0e6f2;background:#f8faff;">
            <button id="appConfirmCancel" type="button" class="secondary-button" style="margin:0;min-width:100px;background:#fff;">Cancel</button>
            <button id="appConfirmProceed" type="button" class="primary-button" style="margin:0;min-width:110px;${tone === "error" ? "background:#d64b4b;border-color:#d64b4b;color:#fff;" : ""}">${tone === "error" ? "Confirm Delete" : "Proceed"}</button>
          </div>
        </section>
      `;
      document.body.appendChild(overlay);

      const cancelBtn = overlay.querySelector("#appConfirmCancel");
      const proceedBtn = overlay.querySelector("#appConfirmProceed");

      const close = function (result) {
        if (overlay.parentNode) {
          document.body.removeChild(overlay);
        }
        resolve(result);
      };

      cancelBtn.addEventListener("click", function () { close(false); });
      proceedBtn.addEventListener("click", function () { close(true); });
      overlay.addEventListener("click", function (event) {
        if (event.target === overlay) { close(false); }
      });
    });
  }

  function openAppMessageBox(title, detail, tone) {
    ensureAppMessageBox();
    appMessageTitle.textContent = title || "Message";
    appMessageText.textContent = String(detail || "");
    appMessageBox.classList.remove("app-message-box--error", "app-message-box--success", "app-message-box--warning");
    if (tone) {
      appMessageBox.classList.add(`app-message-box--${tone}`);
    }
    appMessageOverlay.hidden = false;
  }

  function openTableSetupDialog(onSubmit) {
    const overlay = document.createElement("div");
    overlay.className = "app-message-overlay";
    overlay.innerHTML = `
      <section class="app-message-box app-message-box--info" style="max-width:440px;">
        <header class="app-message-box__header">
          <h3 class="app-message-box__title">Insert Table</h3>
        </header>
        <div class="app-message-box__body">
          <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;">
            <label style="display:flex;flex-direction:column;gap:6px;font-weight:700;color:#12314f;">Rows
              <input id="tableDialogRows" type="number" min="1" value="2" class="table-inline-input">
            </label>
            <label style="display:flex;flex-direction:column;gap:6px;font-weight:700;color:#12314f;">Columns
              <input id="tableDialogCols" type="number" min="1" value="2" class="table-inline-input">
            </label>
          </div>
        </div>
        <footer class="app-message-box__footer" style="display:flex;gap:10px;">
          <button id="tableDialogCancel" type="button" class="table-action-btn danger" style="flex:1;">Cancel</button>
          <button id="tableDialogCreate" type="button" class="table-action-btn" style="flex:1;">Create Table</button>
        </footer>
      </section>
    `;
    const close = function () {
      if (overlay.parentNode) {
        overlay.parentNode.removeChild(overlay);
      }
    };
    overlay.addEventListener("click", function (event) {
      if (event.target === overlay) close();
    });
    overlay.querySelector("#tableDialogCancel").addEventListener("click", close);
    overlay.querySelector("#tableDialogCreate").addEventListener("click", function () {
      const rows = Math.max(1, Number(overlay.querySelector("#tableDialogRows").value || 2));
      const cols = Math.max(1, Number(overlay.querySelector("#tableDialogCols").value || 2));
      close();
      if (typeof onSubmit === "function") {
        onSubmit(rows, cols);
      }
    });
    document.body.appendChild(overlay);
  }

  const nativeAlert = window.alert ? window.alert.bind(window) : null;
  window.alert = function (message) {
    const text = String(message || "");
    const lower = text.toLowerCase();
    let title = "Error";
    let tone = "error";
    if (lower.includes("success")) {
      title = "Success";
      tone = "success";
    } else if (lower.includes("warning")) {
      title = "Warning";
      tone = "warning";
    } else if (lower.includes("confirm") || lower.includes("processed") || lower.includes("prepared")) {
      title = "Message";
      tone = "";
    }
    openAppMessageBox(title, text, tone);
    return undefined;
  };

  const observedFormMessages = new WeakSet();
  let formMessageObserverStarted = false;

  function getToneFromFormMessageClass(className) {
    const cls = String(className || "").toLowerCase();
    if (cls.includes("success")) {
      return { title: "Success", tone: "success" };
    }
    if (cls.includes("warning")) {
      return { title: "Warning", tone: "warning" };
    }
    if (cls.includes("error")) {
      return { title: "Error", tone: "error" };
    }
    return { title: "Message", tone: "" };
  }

  function maybeAnnounceFormMessage(el) {
    if (!el || !el.classList || !el.classList.contains("form-message")) {
      return;
    }
    const text = String(el.textContent || "").trim();
    if (!text) {
      return;
    }
    const toneMeta = getToneFromFormMessageClass(el.className || "");
    openAppMessageBox(toneMeta.title, text, toneMeta.tone);
  }

  function watchFormMessageElement(el) {
    if (!el || observedFormMessages.has(el)) {
      return;
    }
    observedFormMessages.add(el);
    const observer = new MutationObserver(function () {
      maybeAnnounceFormMessage(el);
    });
    observer.observe(el, { characterData: true, childList: true, subtree: true, attributes: true, attributeFilter: ["class"] });
    maybeAnnounceFormMessage(el);
  }

  function startGlobalFormMessageObserver() {
    if (formMessageObserverStarted) {
      return;
    }
    formMessageObserverStarted = true;
    document.querySelectorAll(".form-message").forEach(function (el) {
      watchFormMessageElement(el);
    });
    const rootObserver = new MutationObserver(function (mutations) {
      mutations.forEach(function (mutation) {
        mutation.addedNodes.forEach(function (node) {
          if (!node || node.nodeType !== 1) {
            return;
          }
          if (node.classList && node.classList.contains("form-message")) {
            watchFormMessageElement(node);
          }
          if (node.querySelectorAll) {
            node.querySelectorAll(".form-message").forEach(function (el) {
              watchFormMessageElement(el);
            });
          }
        });
      });
    });
    rootObserver.observe(document.body, { childList: true, subtree: true });
  }

