  function setFormMessage(message, type) {
    studentFormMessage.textContent = message;
    studentFormMessage.className = "form-message" + (type ? ` ${type}` : "");
  }

  function getStudentClassOptions() {
    return database.classes.map(function (classItem) {
      return classItem.name;
    });
  }

  function getTeacherOptions() {
    const names = [];

    database.teachers.forEach(function (teacher) {
      if (teacher.name) {
        names.push(teacher.name);
      }
    });

    database.users.forEach(function (user) {
      if (user.role === "teacher" && user.name && String(user.id || "").indexOf("DEMO") === -1) {
        names.push(user.name);
      }
    });

    database.classes.forEach(function (classItem) {
      if (classItem.classTeacher) {
        names.push(classItem.classTeacher);
      }
    });

    return Array.from(new Set(names)).sort();
  }

