  function getStudentLoginInfo(student) {
    const safeStudent = student || {};
    const users = Array.isArray(database.users) ? database.users : [];
    const studentId = String(safeStudent.id || "");
    const studentName = String(safeStudent.name || "");
    const admissionText = String(safeStudent.admissionNo || "");
    const loginUser = users.find(function (user) {
      return user && user.role === "student" && (user.id === `LOGIN-${studentId}` || user.name === studentName);
    });

    if (loginUser) {
      return {
        status: loginUser.active ? "Active" : "Inactive",
        username: loginUser.email || "-",
        password: loginUser.password || "-"
      };
    }

    const normalizedAdmission = admissionText ? admissionText.toLowerCase() : "";
    const derivedUsername = normalizedAdmission ? `${normalizedAdmission}@student.local` : "-";
    const derivedPassword = normalizedAdmission ? `${normalizedAdmission}123` : "-";
    return {
      status: "Not Created",
      username: derivedUsername,
      password: derivedPassword
    };
  }

  function getEmployees() {
    return (database.teachers || []).map(function (employee) {
      return {
        ...employee,
        designation: employee.designation || employee.role || "Teacher",
        role: employee.role || "Teacher",
        dateOfJoining: employee.dateOfJoining || "",
        monthlySalary: Number(employee.monthlySalary || 0),
        phone: employee.phone || "",
        picture: employee.picture || "",
        fatherOrHusbandName: employee.fatherOrHusbandName || "",
        nationalId: employee.nationalId || "",
        education: employee.education || "",
        gender: employee.gender || "",
        religion: employee.religion || "",
        bloodGroup: employee.bloodGroup || "",
        experience: employee.experience || "",
        email: employee.email || "",
        dateOfBirth: employee.dateOfBirth || "",
        address: employee.address || "",
        status: employee.status || "active"
      };
    });
  }

  function getEmployeeById(employeeId) {
    const targetId = String(employeeId || "");
    return getEmployees().find(function (employee) {
      return String(employee.id || "") === targetId;
    }) || null;
  }

  function getEmployeeLoginInfo(employee) {
    const loginUser = database.users.find(function (user) {
      return user.role === "teacher" && (user.employeeId === employee.id || user.name === employee.name);
    });

    if (loginUser) {
      return {
        status: loginUser.active ? "Active" : "Inactive",
        username: loginUser.email || "-",
        password: loginUser.password || "-"
      };
    }

    const baseName = String(employee.name || "employee").toLowerCase().replace(/\s+/g, ".");
    return {
      status: "Not Created",
      username: `${baseName}@employee.local`,
      password: `${baseName.replace(/\./g, "")}123`
    };
  }

  function saveEmployeeRecord(employeeRecord, originalId) {
    const lookupId = originalId || employeeRecord.id;
    const existingIndex = database.teachers.findIndex(function (employee) {
      return employee.id === lookupId;
    });

    if (existingIndex >= 0) {
      database.teachers[existingIndex] = employeeRecord;
    } else {
      database.teachers.unshift(employeeRecord);
    }

    database.employees = database.teachers.slice();
  }

  function trackDeletion(id) {
    if (!database._deletedIds) database._deletedIds = [];
    if (id && database._deletedIds.indexOf(id) === -1) database._deletedIds.push(id);
  }

  async function deleteEmployeeRecord(employeeId) {
    const employee = getEmployeeById(employeeId);
    if (!employee) {
      return;
    }
    if (!database._deletedIds) database._deletedIds = [];
    if (database._deletedIds.indexOf(employeeId) === -1) database._deletedIds.push(employeeId);
    database.teachers = database.teachers.filter(function (item) {
      return item.id !== employeeId;
    });
    database.employees = (database.employees || []).filter(function (item) {
      return item.id !== employeeId;
    });
    var deletedUser = null;
    database.users = database.users.filter(function (user) {
      var match = user.role === "teacher" && (user.employeeId === employeeId || user.name === employee.name);
      if (match && !deletedUser) deletedUser = user;
      return !match;
    });
    addActivity("Employee deleted", `${employee.name} record was removed.`);
    var changes = [
      { table: "employees", record: employee, operation: "delete" }
    ];
    if (deletedUser) {
      changes.push({ table: "app_users", record: deletedUser, operation: "delete" });
    }
    await saveDatabase("Deleting employee...", changes);
  }

  function ensureEmployeeLogin(employee) {
    const existingUserIndex = database.users.findIndex(function (user) {
      return user.role === "teacher" && (user.employeeId === employee.id || user.name === employee.name);
    });
    const fallback = getEmployeeLoginInfo(employee);

    const loginUser = {
      id: existingUserIndex >= 0 ? database.users[existingUserIndex].id : `EMP-LOGIN-${employee.id}`,
      name: employee.name,
      email: fallback.username,
      password: fallback.password,
      role: "teacher",
      employeeId: employee.id,
      phone: employee.phone || "",
      active: employee.status === "active"
    };

    if (existingUserIndex >= 0) {
      database.users[existingUserIndex] = { ...database.users[existingUserIndex], ...loginUser };
    } else {
      database.users.push(loginUser);
    }
  }

  function getTodayDateISO() {
    const today = new Date();
    return today.getFullYear() + "-" + String(today.getMonth() + 1).padStart(2, "0") + "-" + String(today.getDate()).padStart(2, "0");
  }

  function getCurrentMonthYearISO() {
    const today = new Date();
    return today.getFullYear() + "-" + String(today.getMonth() + 1).padStart(2, "0");
  }

  function renderStats() {
    const statsGrid = document.getElementById("statsGrid");
    if (!statsGrid) return;
    const settings = (database && database.generalSettings) ? database.generalSettings : {};
    const safeAttr = function (value) {
      return String(value == null ? "" : value).replace(/&/g, "&amp;").replace(/"/g, "&quot;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
    };
    
    // Fees card must follow actual collections and total enrolled students.
    const totalEnrolledStudents = Array.isArray(database.students) ? database.students.length : 0;
    const paidStudentIds = new Set(
      (database.fees || [])
        .filter(function (fee) {
          return fee.status === "paid" && Number(fee.remaining || 0) === 0;
        })
        .map(function (fee) {
          return String(fee.studentId || "").trim();
        })
        .filter(Boolean)
    );
    const paidStudentsCount = paidStudentIds.size;
    
    // Get attendance for TODAY only
    const todayISO = getTodayDateISO();
    const attendanceArr = Array.isArray(database.attendance) ? database.attendance : [];
    const studentAttendance = attendanceArr.filter(function (item) {
      const attendanceDate = (item.date || "").substring(0, 10);
      return (item.studentId || !item.entityType || item.entityType === "student") && attendanceDate === todayISO;
    });
    const presentAttendance = studentAttendance.filter(function (item) { return item.status === "Present"; }).length;
    const presentOnLeaveAttendance = studentAttendance.filter(function (item) { return item.status === "Present" || item.status === "On-leave"; }).length;
    const totalStudents = (Array.isArray(database.students) ? database.students : []).filter(function (item) { return item.status === "active"; }).length;
    const attendancePercentage = totalStudents > 0 ? Math.round((presentOnLeaveAttendance / totalStudents) * 100) : 0;

    // Get monthly fees breakdown (all months with records)
    const feesByMonth = {};
    (database.fees || []).forEach(function (item) {
      const feeMonth = item.feeMonth || item.month || "Unknown";
      if (!feesByMonth[feeMonth]) {
        feesByMonth[feeMonth] = { total: 0, paid: 0 };
      }
      feesByMonth[feeMonth].total += 1;
      if (item.status === "paid") {
        feesByMonth[feeMonth].paid += 1;
      }
    });
    const monthlyFeesSummary = Object.keys(feesByMonth).length > 0 
      ? `${Object.keys(feesByMonth).reduce(function(sum, m) { return sum + feesByMonth[m].paid; }, 0)} paid in ${Object.keys(feesByMonth).length} months`
      : "No fee records";

    const validClassNames = new Set((database.classes || []).map(function (classItem) {
      return String(classItem.name || "").trim();
    }).filter(Boolean));
    const linkedSubjectsCount = (database.subjects || []).filter(function (subject) {
      const className = String(subject.className || "").trim();
      return className && validClassNames.has(className);
    }).length;

    const cards = [
      {
        icon: '<img src="./assets/students.png" class="menu-icon__img" alt="Students">',
        tone: "students",
        route: "all-students",
        label: "Students",
        value: (database.students || []).length,
        note: `${totalStudents} active records`
      },
      {
        icon: '<img src="./assets/employees.png" class="menu-icon__img" alt="Employees">',
        tone: "teachers",
        route: "all-employees",
        label: "Employees",
        value: (database.employees || database.teachers || []).length,
        note: `${linkedSubjectsCount} subjects assigned`
      },
      {
        icon: '<img src="./assets/classes.png" class="menu-icon__img" alt="Classes">',
        tone: "classes",
        route: "all-classes",
        label: "Classes",
        value: (database.classes || []).length,
        note: `${(database.classes || []).length} academic groups`
      },
      {
        icon: '<img src="./assets/fees.png" class="menu-icon__img" alt="Fees">',
        tone: "fees",
        route: "generate-fees-invoice",
        label: "Fees",
        value: `${paidStudentsCount}/${totalEnrolledStudents}`,
        note: "Paid students / enrolled"
      },
      {
        icon: '<img src="./assets/attendance.png" class="menu-icon__img" alt="Attendance">',
        tone: "attendance",
        route: "students-attendance",
        label: "Attendance",
        value: `${presentAttendance}/${studentAttendance.length}`,
        note: "Today's attendance"
      },
      {
        icon: '<img src="./assets/parents.png" class="menu-icon__img" alt="Parents">',
        tone: "parents",
        route: "parents-info-report",
        label: "Parents",
        value: (function () {
          var phones = new Set();
          (database.students || []).forEach(function (s) {
            if (s.fatherPhone) phones.add(s.fatherPhone);
            if (s.motherPhone) phones.add(s.motherPhone);
          });
          return phones.size;
        })(),
        note: "Associated with students"
      },
      {
        icon: '<img src="./assets/subjects.png" class="menu-icon__img" alt="Subjects">',
        tone: "subjects",
        route: "classes-with-subjects",
        label: "Subjects",
        value: linkedSubjectsCount,
        note: "Linked subjects configured"
      },
      {
        icon: '<img src="./assets/dashboard.png" class="menu-icon__img" alt="Activity">',
        tone: "activity",
        route: "students-info-report",
        label: "Activity",
        value: (database.activityLogs || []).length,
        note: "System events stored"
      }
    ];

    statsGrid.innerHTML = cards.map(function (card) {
      return `
        <article class="stat-card dashboard-stat-card dashboard-stat-card--${safeAttr(card.tone || "default")}" data-dashboard-route="${safeAttr(card.route || "")}" role="button" tabindex="0">
          <div class="stat-card__top">
            <div>
              <p class="panel-label">${card.label}</p>
              <strong>${card.value}</strong>
            </div>
            <span class="menu-icon">${card.icon}</span>
          </div>
          <span class="metric-note">${card.note}</span>
        </article>
      `;
    }).join("");
  }

  function handleDashboardCardNavigation(event) {
    const card = event.target.closest("[data-dashboard-route]");
    if (!card) {
      return;
    }
    const route = card.getAttribute("data-dashboard-route");
    if (!route) {
      return;
    }
    setRoute(route);
  }

