  function renderDashboardMiniCards() {
    renderDashboardNotices();
    renderDashboardEvents();
    var viewAllBtns = document.querySelectorAll("[data-dashboard-route]");
    viewAllBtns.forEach(function (btn) {
      btn.addEventListener("click", function () {
        setRoute(btn.getAttribute("data-dashboard-route"));
      });
    });
  }

  function renderDashboardNotices() {
    var el = document.getElementById("dashboardNoticeBoard");
    if (!el) return;
    var cache = window.SagarSoftCache;
    var notices = (cache && typeof cache.getNotices === "function") ? cache.getNotices() : [];
    if (!notices.length) notices = Array.isArray(database.generalSettings.notices) ? database.generalSettings.notices : [];
    var now = new Date();
    var todayStr = now.getFullYear() + "-" + String(now.getMonth() + 1).padStart(2, "0") + "-" + String(now.getDate()).padStart(2, "0");
    var active = notices.filter(function (n) {
      if (n.pushed === false) return false;
      if (n.expiryDate && n.expiryDate < todayStr) return false;
      return true;
    });
    active.sort(function (a, b) {
      var da = a.createdAt || "";
      var db = b.createdAt || "";
      return da > db ? -1 : da < db ? 1 : 0;
    });
    var recent = active.slice(0, 5);
    if (!recent.length) {
      el.innerHTML = '<div class="dash-empty"><i class="fas fa-bullhorn"></i>No active notices.</div>';
      return;
    }
    el.innerHTML = recent.map(function (n) {
      var priority = n.priority || "normal";
      var priorityLabel = priority.charAt(0).toUpperCase() + priority.slice(1);
      var date = n.createdAt || "";
      var content = (n.content || "").replace(/\n/g, " ");
      var preview = content.length > 100 ? content.substring(0, 100) + "..." : content;
      return '<div class="dash-notice" data-notice-id="' + escapeAttr(n.id) + '" style="cursor:pointer;">' +
        '<span class="dash-notice__dot dash-notice__dot--' + escapeAttr(priority) + '"></span>' +
        '<div class="dash-notice__content">' +
          '<p class="dash-notice__title">' + escapeHtml(n.title) + '</p>' +
          '<p class="dash-notice__preview" style="font-size:0.72rem;color:#5a7a96;margin:2px 0 0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:100%;">' + escapeHtml(preview) + '</p>' +
          '<p class="dash-notice__meta" style="margin:3px 0 0;">' +
            '<span style="font-size:0.68rem;color:#8a97a5;">' + escapeHtml(date) + '</span>' +
            ' <span style="font-size:0.6rem;padding:1px 6px;border-radius:8px;background:' + (priority === "urgent" ? "#fde8e8" : priority === "important" ? "#fff3e0" : "#e8f5e9") + ';color:' + (priority === "urgent" ? "#d32f2f" : priority === "important" ? "#e65100" : "#2e7d32") + ';font-weight:600;">' + escapeHtml(priorityLabel) + '</span>' +
            (n.expiryDate ? ' <span style="font-size:0.65rem;color:#999;">Exp: ' + escapeHtml(n.expiryDate) + '</span>' : '') +
          '</p>' +
        '</div>' +
      '</div>';
    }).join("");
    el.querySelectorAll(".dash-notice[data-notice-id]").forEach(function (card) {
      card.addEventListener("click", function () {
        var nid = card.getAttribute("data-notice-id");
        var notice = active.find(function (n) { return n.id === nid; });
        if (!notice) return;
        var content = (notice.content || "").replace(/\n/g, "<br>");
        openAppMessageBox(notice.title || "Notice", content, "info");
      });
    });
  }

  function renderDashboardEvents() {
    var el = document.getElementById("dashboardEventCalendar");
    if (!el) return;
    var cache = window.SagarSoftCache;
    var events = (cache && typeof cache.getEvents === "function") ? cache.getEvents() : [];
    if (!events.length) events = Array.isArray(database.generalSettings.events) ? database.generalSettings.events : [];
    var today = new Date();
    var todayStr = today.getFullYear() + "-" + String(today.getMonth() + 1).padStart(2, "0") + "-" + String(today.getDate()).padStart(2, "0");

    var year = today.getFullYear();
    var month = today.getMonth();
    var monthNames = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
    var dayNames = ["Su", "Mo", "Tu", "We", "Th", "Fr", "Sa"];
    var firstDay = new Date(year, month, 1).getDay();
    var daysInMonth = new Date(year, month + 1, 0).getDate();

    var birthdays = [];
    (database.students || []).forEach(function (st) {
      if (String(st.status || "").toLowerCase() !== "active") return;
      if (!st.dateOfBirth) return;
      var dob = new Date(st.dateOfBirth);
      var dobMonth = dob.getMonth();
      var dobDay = dob.getDate();
      if (dobMonth === month) {
        var bdayStr = year + "-" + String(dobMonth + 1).padStart(2, "0") + "-" + String(dobDay).padStart(2, "0");
        var age = year - dob.getFullYear();
        birthdays.push({
          name: st.name || "Student",
          day: dobDay,
          date: bdayStr,
          age: age,
          isToday: dobDay === today.getDate()
        });
      }
    });
    birthdays.sort(function (a, b) { return a.day > b.day ? 1 : a.day < b.day ? -1 : 0; });

    var calHtml = '<div class="dashboard-calendar-layout">';

    calHtml += '<div class="dash-cal">';
    calHtml += '<div class="dash-cal__header"><strong>' + monthNames[month] + ' ' + year + '</strong></div>';
    calHtml += '<div class="dash-cal__grid">';
    for (var d = 0; d < 7; d++) { calHtml += '<div class="dash-cal__dayname">' + dayNames[d] + '</div>'; }
    for (var c = 0; c < firstDay; c++) { calHtml += '<div class="dash-cal__cell dash-cal__cell--empty"></div>'; }
    for (var day = 1; day <= daysInMonth; day++) {
      var ds = year + "-" + String(month + 1).padStart(2, "0") + "-" + String(day).padStart(2, "0");
      var isToday = day === today.getDate();
      var dayEvts = events.filter(function (ev) { var sd = ev.date || ev.start_date || ""; return sd === ds; });
      var hasEvent = dayEvts.length > 0;
      var hasBday = birthdays.some(function (b) { return b.day === day; });
      var evType = "";
      if (hasEvent) { evType = dayEvts[0].type || dayEvts[0].event_type || "custom"; }
      var cls = "dash-cal__cell";
      if (isToday) cls += " dash-cal__cell--today";
      if (hasEvent) cls += " dash-cal__cell--event dash-cal__cell--" + escapeAttr(evType);
      if (hasBday && !hasEvent) cls += " dash-cal__cell--event dash-cal__cell--birthday";
      var title = day;
      if (hasBday) { var bNames = birthdays.filter(function (b) { return b.day === day; }).map(function (b) { return b.name; }).join(", "); title = bNames; }
      if (hasEvent) { title = dayEvts.map(function (ev) { return ev.title; }).join(", "); }
      calHtml += '<div class="' + cls + '" title="' + escapeAttr(title) + '">' + day + '</div>';
    }
    calHtml += '</div></div>';

    calHtml += '<div class="dash-cal__side">';
    var upcoming = events.filter(function (ev) {
      var sd = ev.date || ev.start_date || "";
      return sd >= todayStr;
    }).sort(function (a, b) {
      var da = a.date || a.start_date || "";
      var db = b.date || b.start_date || "";
      return da > db ? 1 : da < db ? -1 : 0;
    }).slice(0, 3);
    if (upcoming.length) {
      calHtml += '<div class="dash-events-upcoming">';
      calHtml += '<div class="dash-events-upcoming__header"><strong>Upcoming</strong></div>';
      upcoming.forEach(function (ev) {
        var evDate = ev.date || ev.start_date || "";
        var d = new Date(evDate);
        var dayLabel = d.getDate() + " " + ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"][d.getMonth()];
        var type = ev.type || ev.event_type || "custom";
        calHtml += '<div class="dash-events-upcoming__item">' +
          '<span class="dash-events-upcoming__date">' + dayLabel + '</span>' +
          '<span class="dash-events-upcoming__dot dash-events-upcoming__dot--' + escapeAttr(type) + '"></span>' +
          '<span class="dash-events-upcoming__title">' + escapeHtml(ev.title) + '</span>' +
        '</div>';
      });
      calHtml += '</div>';
    }

    if (birthdays.length) {
      calHtml += '<div class="dash-birthdays">';
      calHtml += '<div class="dash-birthdays__header"><strong>Birthdays</strong></div>';
      birthdays.forEach(function (b) {
        var cls = b.isToday ? " dash-birthdays__item--today" : "";
        calHtml += '<div class="dash-birthdays__item' + cls + '">' +
          '<span class="dash-birthdays__day">' + b.day + '</span>' +
          '<span class="dash-birthdays__name">' + escapeHtml(b.name) + '</span>' +
          '<span class="dash-birthdays__age">' + b.age + ' yrs</span>' +
        '</div>';
      });
      calHtml += '</div>';
    }
    calHtml += '</div></div>';
    el.innerHTML = calHtml;
  }

  function getMonthKeyFromValue(value) {
    const raw = String(value || "").trim();
    if (!raw) {
      return "";
    }
    const isoMatch = raw.match(/^(\d{4})-(\d{2})/);
    if (isoMatch) {
      return `${isoMatch[1]}-${isoMatch[2]}`;
    }
    const parsed = new Date(raw);
    if (!Number.isNaN(parsed.getTime())) {
      return `${parsed.getFullYear()}-${String(parsed.getMonth() + 1).padStart(2, "0")}`;
    }
    const monthNames = {
      january: "01", jan: "01",
      february: "02", feb: "02",
      march: "03", mar: "03",
      april: "04", apr: "04",
      may: "05",
      june: "06", jun: "06",
      july: "07", jul: "07",
      august: "08", aug: "08",
      september: "09", sep: "09",
      october: "10", oct: "10",
      november: "11", nov: "11",
      december: "12", dec: "12"
    };
    const labelMatch = raw.toLowerCase().match(/([a-z]+)\s+(\d{4})/);
    if (labelMatch && monthNames[labelMatch[1]]) {
      return `${labelMatch[2]}-${monthNames[labelMatch[1]]}`;
    }
    return "";
  }

  function purgeUntouchedLegacyFinanceData(settings) {
    if (!settings) {
      return false;
    }
    let changed = false;
    settings.accountsLedger = Array.isArray(settings.accountsLedger) ? settings.accountsLedger : [];
    settings.salaryPayments = Array.isArray(settings.salaryPayments) ? settings.salaryPayments : [];

    if (!settings.__accountsLedgerUserTouched && settings.accountsLedger.length) {
      settings.__accountsLedgerUserTouched = true;
      settings.__accountsLedgerLegacyClearedV1 = true;
      settings.__accountsLedgerLegacyClearedV2 = true;
      changed = true;
    }

    if (!settings.__salaryPaymentsUserTouched && settings.salaryPayments.length) {
      settings.salaryPayments = [];
      settings.__salaryPaymentsLegacyClearedV1 = true;
      changed = true;
    }

    return changed;
  }

  function calculateFinancialSummary(options) {
    options = options || {};
    var settings = (database && database.generalSettings) ? database.generalSettings : {};
    var accountsLedger = Array.isArray(settings.accountsLedger) ? settings.accountsLedger : [];
    var salaryPayments = Array.isArray(settings.salaryPayments) ? settings.salaryPayments : [];
    var fromDate = options.from || "";
    var toDate = options.to || "";
    var monthKey = options.monthKey || "";
    function matchesFilter(dateStr) {
      if (monthKey) {
        var itemMonth = getMonthKeyFromValue(dateStr);
        return itemMonth ? itemMonth === monthKey : false;
      }
      if (fromDate || toDate) {
        var ds = String(dateStr || "");
        if (!ds || !fromDate || !toDate) return false;
        return ds >= fromDate && ds <= toDate;
      }
      return true;
    }
    var incomeEntries = accountsLedger.filter(function (item) {
      return String(item.type || "").toLowerCase() === "income" && matchesFilter(item.date || item.createdAt);
    });
    var reversalEntries = accountsLedger.filter(function (item) {
      return String(item.type || "").toLowerCase() === "expense" &&
        String(item.category || "").toLowerCase().indexOf("reversed") !== -1 &&
        matchesFilter(item.date || item.createdAt);
    });
    var expenseEntries = accountsLedger.filter(function (item) {
      return String(item.type || "").toLowerCase() === "expense" &&
        String(item.category || "").toLowerCase().indexOf("reversed") === -1 &&
        matchesFilter(item.date || item.createdAt);
    });
    var salaryEntries = salaryPayments.filter(function (item) {
      return matchesFilter(item.paymentDate || item.date || item.salaryMonth || item.createdAt);
    });
    var grossIncome = incomeEntries.reduce(function (sum, item) { return sum + Number(item.amount || 0); }, 0);
    var totalReversals = reversalEntries.reduce(function (sum, item) { return sum + Number(item.amount || 0); }, 0);
    var revenue = grossIncome - totalReversals;
    var expenses = expenseEntries.reduce(function (sum, item) { return sum + Number(item.amount || 0); }, 0);
    var salaries = salaryEntries.reduce(function (sum, item) { return sum + Number(item.netSalary || item.salaryAmount || 0); }, 0);
    var profit = revenue - expenses - salaries;
    return {
      revenue: revenue,
      income: revenue,
      grossIncome: grossIncome,
      totalReversals: totalReversals,
      expenses: expenses,
      salaries: salaries,
      totalExpenses: expenses + salaries,
      profit: profit,
      net: profit
    };
  }

  function getDashboardMonthFinance() {
    var currentMonth = getCurrentMonthYearISO();
    var summary = calculateFinancialSummary({ monthKey: currentMonth });
    return {
      currentMonth: currentMonth,
      totalIncome: summary.revenue,
      totalSalaries: summary.salaries,
      totalExpenses: summary.expenses,
      incomeTotal: summary.revenue,
      expenseTotal: summary.totalExpenses,
      totalProfit: summary.profit
    };
  }

  function renderInsights() {
    const insightList = document.getElementById("insightList");
    if (!insightList) return;
    const currentMonth = getCurrentMonthYearISO();
    const finance = getDashboardMonthFinance();
    const unpaidCount = database.fees.filter(function (item) {
      const statusOk = item.status === "unpaid" || Number(item.remaining || 0) > 0;
      const monthOk = !item.feeMonth && !item.month ? true : getMonthKeyFromValue(item.feeMonth || item.month || item.date || item.paymentDate) === currentMonth;
      return statusOk && monthOk;
    }).length;
    const absentCount = database.attendance.filter(function (item) {
      const isStudentAttendance = item.studentId || !item.entityType || item.entityType === "student";
      const dateOk = !item.date || String(item.date).slice(0, 10) === getTodayDateISO();
      return isStudentAttendance && item.status === "Absent" && dateOk;
    }).length;
    const inactiveStudents = database.students.filter(function (item) { return item.status === "inactive"; }).length;

    const insights = [];
    if (unpaidCount > 0) {
      insights.push({
        badge: "FN",
        title: `${unpaidCount} unpaid fee record${unpaidCount === 1 ? "" : "s"} this month`,
        text: "Open Fees Defaulters to follow up pending payments.",
        route: "fees-defaulters"
      });
    }
    if (absentCount > 0) {
      insights.push({
        badge: "AT",
        title: `${absentCount} student absence${absentCount === 1 ? "" : "s"} today`,
        text: "Open Students Attendance Report to review attendance.",
        route: "students-attendance-report"
      });
    }
    if (inactiveStudents > 0) {
      insights.push({
        badge: "SR",
        title: `${inactiveStudents} inactive student profile${inactiveStudents === 1 ? "" : "s"}`,
        text: "Open Active / Inactive Students to review records.",
        route: "students-active-inactive"
      });
    }
    if (finance.totalIncome || finance.totalSalaries || finance.totalExpenses) {
      insights.push({
        badge: "PF",
        title: `Monthly profit snapshot: ${finance.totalProfit}`,
        text: "Open Accounts Report to review income, fees, salary and expenses.",
        route: "accounts-report"
      });
    }

    if (!insights.length) {
      insightList.innerHTML = `
        <article class="insight-item">
          <span class="insight-item__badge icon-button">OK</span>
          <div>
            <strong>No urgent insights right now</strong>
            <p>Fees, attendance, students and accounts will appear here when there is actionable data.</p>
          </div>
        </article>
      `;
      return;
    }

    insightList.innerHTML = insights.map(function (item) {
      return `
        <article class="insight-item" data-insight-route="${escapeAttr(item.route || "dashboard")}" style="cursor:pointer;">
          <span class="insight-item__badge icon-button">${escapeHtml(item.badge)}</span>
          <div>
            <strong>${escapeHtml(item.title)}</strong>
            <p>${escapeHtml(item.text)}</p>
          </div>
        </article>
      `;
    }).join("");
    insightList.querySelectorAll("[data-insight-route]").forEach(function (item) {
      item.addEventListener("click", function () {
        setRoute(item.getAttribute("data-insight-route") || "dashboard");
      });
    });
  }

