    function normalizeFeeMonthLabel(monthValue) {
      const value = String(monthValue || "").trim();
      if (/^\d{4}-\d{2}$/.test(value)) {
        const parts = value.split("-");
        const year = Number(parts[0]);
        const month = Number(parts[1]);
        const monthNames = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
        if (month >= 1 && month <= 12) {
          return `${monthNames[month - 1]}, ${year}`;
        }
      }
      return value;
    }

    function buildFeeMonthOptionList() {
      const now = new Date();
      const options = [];
      for (let offset = -6; offset <= 18; offset += 1) {
        const date = new Date(now.getFullYear(), now.getMonth() + offset, 1);
        const year = date.getFullYear();
        const month = String(date.getMonth() + 1).padStart(2, "0");
        const value = `${year}-${month}`;
        options.push(`<option value="${value}">${normalizeFeeMonthLabel(value)}</option>`);
      }
      return options.join("");
    }

