  function setStudentRoute(route, options) {
    const keepFormData = Boolean(options && options.preserveForm);
    currentStudentRoute = route;

    if (route === "students-active-inactive" && studentStatusFilter.value === "all") {
      studentStatusFilter.value = "active";
    }

    if (route === "all-students") {
      studentStatusFilter.value = "all";
      allStudentsSearchInput.value = "";
    }

    if (route === "new-class") {
      setClassMessage("", "");
    }

    if (route === "classes-with-subjects") {
      setClassesWithSubjectsMessage("", "");
    }

    if (route === "assign-subjects") {
      setAssignSubjectsMessage("", "");
      assignSubjectsTitle.textContent = "Assign Subjects";
      populateAssignSubjectsForm(assignSubjectsClassInput.value || "");
    }

    if (route === "students-active-inactive") {
      studentStatusSearchInput.value = "";
      studentStatusClassFilter.value = "all";
    }

    if (route === "admission-letter") {
      admissionLetterSearchInput.value = "";
      selectedAdmissionStudentId = null;
      if (admissionLetterPreviewArea) admissionLetterPreviewArea.style.display = "none";
      if (admissionLetterLoading) admissionLetterLoading.style.display = "none";
      if (admissionDetailCard) admissionDetailCard.style.display = "none";
    }

    if (route === "student-id-cards") {
      studentIdCardsSearchInput.value = "";
      studentIdCardsClassFilter.value = "all";
    }

    if (route === "print-basic-list") {
      printBasicListSearchInput.value = "";
      printBasicListClassFilter.value = "all";
    }

    if (route === "students-manage-login") {
      studentsManageLoginSearchInput.value = "";
    }

    if (route === "promote-students") {
      promoteStudentsSearchInput.value = "";
      promoteStudentsClassFilter.value = "all";
      promoteTargetClassSelect.value = "";
      promoteStudentsMessage.textContent = "";
      promoteStudentsMessage.className = "form-message";
      promoteSelectionState = {};
    }

    if (route === "parents-manage-login") {
      // No specific initialization needed
    }

    renderStudentsWorkspace();

    if (route === "students-add-new") {
      if (!keepFormData) {
        populateStudentForm(null);
      }
      studentForm.scrollIntoView({ behavior: "smooth", block: "start" });
    }
  }

  let dashboardClockTimer = null;


  function buildDashboardBars(rows, maxValue) {
    var total = rows.reduce(function (sum, r) { return sum + Number(r.value || 0); }, 0);
    if (!total) return '<p class="empty-state">No attendance data.</p>';

    var present = Number(rows[0].value || 0);
    var leave = Number(rows[1].value || 0);
    var absent = Number(rows[2].value || 0);
    var unmarked = Number(rows[3].value || 0);

    var pctPresent = total > 0 ? Math.round((present / total) * 100) : 0;
    var pctLeave = total > 0 ? Math.round((leave / total) * 100) : 0;
    var pctAbsent = total > 0 ? Math.round((absent / total) * 100) : 0;
    var pctUnmarked = total > 0 ? Math.round((unmarked / total) * 100) : 0;

    var radius = 70;
    var circumference = 2 * Math.PI * radius;

    function segArc(pct) { return (pct / 100) * circumference; }

    var offset = 0;
    var presentLen = segArc(pctPresent);
    var leaveLen = segArc(pctLeave);
    var absentLen = segArc(pctAbsent);
    var unmarkedLen = segArc(pctUnmarked);

    var svg = '<div class="attendance-donut-wrapper">';
    svg += '<div class="attendance-donut">';
    svg += '<svg viewBox="0 0 180 180" class="attendance-donut__svg">';
    svg += '<circle cx="90" cy="90" r="' + radius + '" fill="none" stroke="#e2e8f0" stroke-width="22"/>';

    if (pctPresent > 0) {
      svg += '<circle cx="90" cy="90" r="' + radius + '" fill="none" stroke="#10b981" stroke-width="22" stroke-linecap="round" stroke-dasharray="' + presentLen + ' ' + (circumference - presentLen) + '" stroke-dashoffset="' + (-offset) + '" class="donut-seg donut-seg--present"/>';
      offset += presentLen;
    }
    if (pctLeave > 0) {
      svg += '<circle cx="90" cy="90" r="' + radius + '" fill="none" stroke="#f59e0b" stroke-width="22" stroke-linecap="round" stroke-dasharray="' + leaveLen + ' ' + (circumference - leaveLen) + '" stroke-dashoffset="' + (-offset) + '" class="donut-seg donut-seg--leave"/>';
      offset += leaveLen;
    }
    if (pctAbsent > 0) {
      svg += '<circle cx="90" cy="90" r="' + radius + '" fill="none" stroke="#ef4444" stroke-width="22" stroke-linecap="round" stroke-dasharray="' + absentLen + ' ' + (circumference - absentLen) + '" stroke-dashoffset="' + (-offset) + '" class="donut-seg donut-seg--absent"/>';
      offset += absentLen;
    }
    if (pctUnmarked > 0) {
      svg += '<circle cx="90" cy="90" r="' + radius + '" fill="none" stroke="#94a3b8" stroke-width="22" stroke-linecap="round" stroke-dasharray="' + unmarkedLen + ' ' + (circumference - unmarkedLen) + '" stroke-dashoffset="' + (-offset) + '" class="donut-seg donut-seg--unmarked"/>';
    }

    svg += '<text x="90" y="84" text-anchor="middle" class="donut-center-value">' + present + '</text>';
    svg += '<text x="90" y="104" text-anchor="middle" class="donut-center-label">Present</text>';
    svg += '</svg>';
    svg += '</div>';
    svg += '<div class="attendance-donut__legend">';
    svg += '<div class="attendance-donut__legend-item"><span class="attendance-donut__legend-dot" style="background:#10b981;"></span><span class="attendance-donut__legend-label">Present</span><strong>' + present + '</strong><span class="attendance-donut__legend-pct">' + pctPresent + '%</span></div>';
    svg += '<div class="attendance-donut__legend-item"><span class="attendance-donut__legend-dot" style="background:#f59e0b;"></span><span class="attendance-donut__legend-label">On Leave</span><strong>' + leave + '</strong><span class="attendance-donut__legend-pct">' + pctLeave + '%</span></div>';
    svg += '<div class="attendance-donut__legend-item"><span class="attendance-donut__legend-dot" style="background:#ef4444;"></span><span class="attendance-donut__legend-label">Absent</span><strong>' + absent + '</strong><span class="attendance-donut__legend-pct">' + pctAbsent + '%</span></div>';
    svg += '<div class="attendance-donut__legend-item"><span class="attendance-donut__legend-dot" style="background:#94a3b8;"></span><span class="attendance-donut__legend-label">Unmarked</span><strong>' + unmarked + '</strong><span class="attendance-donut__legend-pct">' + pctUnmarked + '%</span></div>';
    svg += '</div></div>';
    return svg;
  }

  function getDashboardFinanceSeries() {
    var monthNames = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
    var today = new Date();
    var months = [];
    for (var offset = 5; offset >= 0; offset -= 1) {
      var date = new Date(today.getFullYear(), today.getMonth() - offset, 1);
      var key = date.getFullYear() + "-" + String(date.getMonth() + 1).padStart(2, "0");
      months.push({ key: key, label: monthNames[date.getMonth()] + " " + date.getFullYear() });
    }
    return months.map(function (month) {
      var summary = calculateFinancialSummary({ monthKey: month.key });
      return { label: month.label, income: summary.revenue, expense: summary.totalExpenses };
    });
  }

  function buildSmoothPath(points) {
    if (!points.length) {
      return "";
    }
    if (points.length === 1) {
      return `M ${points[0].x} ${points[0].y}`;
    }
    let path = `M ${points[0].x} ${points[0].y}`;
    for (let index = 1; index < points.length; index += 1) {
      const previous = points[index - 1];
      const current = points[index];
      const middleX = (previous.x + current.x) / 2;
      path += ` C ${middleX} ${previous.y}, ${middleX} ${current.y}, ${current.x} ${current.y}`;
    }
    return path;
  }

  function buildDashboardFinancePictureGraph(finance, currencySymbol) {
    const series = getDashboardFinanceSeries();
    const maxValue = Math.max(1, ...series.map(function (row) {
      return Math.max(Number(row.income || 0), Number(row.expense || 0));
    }));
    const width = 760;
    const height = 300;
    const left = 54;
    const right = 24;
    const top = 34;
    const bottom = 54;
    const chartWidth = width - left - right;
    const chartHeight = height - top - bottom;
    const xStep = series.length > 1 ? chartWidth / (series.length - 1) : chartWidth;
    const yFor = function (value) {
      return bottom + chartHeight - ((Number(value || 0) / maxValue) * chartHeight);
    };
    const incomePoints = series.map(function (row, index) {
      return { x: left + (index * xStep), y: yFor(row.income), value: row.income };
    });
    const expensePoints = series.map(function (row, index) {
      return { x: left + (index * xStep), y: yFor(row.expense), value: row.expense };
    });
    const baseY = bottom + chartHeight;
    const incomeLine = buildSmoothPath(incomePoints);
    const expenseLine = buildSmoothPath(expensePoints);
    const incomeArea = `${incomeLine} L ${incomePoints[incomePoints.length - 1].x} ${baseY} L ${incomePoints[0].x} ${baseY} Z`;
    const expenseArea = `${expenseLine} L ${expensePoints[expensePoints.length - 1].x} ${baseY} L ${expensePoints[0].x} ${baseY} Z`;
    const gridRows = [0, 0.25, 0.5, 0.75, 1].map(function (ratio) {
      const y = bottom + (chartHeight * ratio);
      const value = Math.round(maxValue * (1 - ratio));
      return `<line x1="${left}" y1="${y}" x2="${width - right}" y2="${y}"></line><text x="${left - 10}" y="${y + 4}" text-anchor="end">${value}</text>`;
    }).join("");
    const monthLabels = series.map(function (row, index) {
      const x = left + (index * xStep);
      return `<text class="month-label" x="${x}" y="${height - 18}" text-anchor="middle">${escapeHtml(row.label)}</text>`;
    }).join("");
    const incomeDots = incomePoints.map(function (point) {
      return `<circle class="income-dot" cx="${point.x}" cy="${point.y}" r="4"><title>${currencySymbol} ${Math.round(point.value)}</title></circle>`;
    }).join("");
    const expenseDots = expensePoints.map(function (point) {
      return `<circle class="expense-dot" cx="${point.x}" cy="${point.y}" r="4"><title>${currencySymbol} ${Math.round(point.value)}</title></circle>`;
    }).join("");
    const totalIncome = Math.round(Number(finance.incomeTotal || 0));
    const totalExpense = Math.round(Number(finance.expenseTotal || 0));
    return `
      <div class="dashboard-finance-picture" aria-label="Income vs expense graph">
        <div class="dashboard-finance-picture__legend">
          <span><i class="expense"></i> Expenses ${currencySymbol} ${totalExpense}</span>
          <span><i class="income"></i> Income ${currencySymbol} ${totalIncome}</span>
        </div>
        <svg viewBox="0 0 ${width} ${height}" role="img" aria-label="Monthly income and expense">
          <g class="finance-grid">${gridRows}</g>
          <path class="expense-area" d="${expenseArea}"></path>
          <path class="income-area" d="${incomeArea}"></path>
          <path class="expense-line" d="${expenseLine}"></path>
          <path class="income-line" d="${incomeLine}"></path>
          ${expenseDots}
          ${incomeDots}
          <g class="finance-months">${monthLabels}</g>
        </svg>
      </div>
    `;
  }

  function renderDashboardAnalytics() {
    const financeChart = document.getElementById("dashboardFinanceChart");
    const attendanceBars = document.getElementById("dashboardAttendanceBar");
    if (!financeChart || !attendanceBars) {
      return;
    }

    const finance = getDashboardMonthFinance();
    const currencySymbol = (database.generalSettings && database.generalSettings.accountSettings && database.generalSettings.accountSettings.symbol)
      ? database.generalSettings.accountSettings.symbol
      : "Rs";
    const income = Number(finance.totalIncome || 0);
    const expense = Number(finance.totalSalaries || 0) + Number(finance.totalExpenses || 0);
    const totalFinance = income + expense;
    const hasFinanceSeries = getDashboardFinanceSeries().some(function (row) {
      return Number(row.income || 0) || Number(row.expense || 0);
    });

    financeChart.innerHTML = (totalFinance || hasFinanceSeries)
      ? buildDashboardFinancePictureGraph(finance, currencySymbol)
      : `<p class="empty-state">No finance entries yet.</p>`;

    // Get TODAY's student attendance only
    const todayISO = getTodayDateISO();
    const todayAttendance = (database.attendance || []).filter(function (row) {
      const attendanceDate = (row.date || "").substring(0, 10);
      const isStudentAttendance = row.studentId || !row.entityType || row.entityType === "student";
      return isStudentAttendance && attendanceDate === todayISO;
    });
    const present = todayAttendance.filter(function (row) { return row.status === "Present"; }).length;
    const leave = todayAttendance.filter(function (row) { return row.status === "On-leave"; }).length;
    const absent = todayAttendance.filter(function (row) { return row.status === "Absent"; }).length;
    const totalStudents = (database.students || []).filter(function (student) { return String(student.status || "active").toLowerCase() !== "inactive"; }).length;
    const totalAttendance = Math.max(todayAttendance.length, present + leave + absent);
    const unmarked = Math.max(0, totalStudents - totalAttendance);
    const attRows = [
      { label: "Present", value: present },
      { label: "On-leave", value: leave },
      { label: "Absent", value: absent },
      { label: "Unmarked", value: unmarked }
    ];
    attendanceBars.innerHTML = (totalAttendance || unmarked)
      ? buildDashboardBars(attRows, Math.max.apply(null, attRows.map(function (item) { return item.value; })))
      : `<p class="empty-state">No students found for attendance overview.</p>`;
    financeChart.style.cursor = "pointer";
    financeChart.onclick = function () { setRoute("accounts-report"); };
    attendanceBars.style.cursor = "pointer";
    attendanceBars.onclick = function () { setRoute("students-attendance"); };
  }

  function refreshAttendanceOverview() {
    const el = document.getElementById("dashboardAttendanceBar");
    if (!el) return;
    const todayISO = getTodayDateISO();
    const todayAttendance = (database.attendance || []).filter(function (row) {
      const isStudentAttendance = row.studentId || !row.entityType || row.entityType === "student";
      return isStudentAttendance && (row.date || "").substring(0, 10) === todayISO;
    });
    const present = todayAttendance.filter(function (r) { return r.status === "Present"; }).length;
    const leave = todayAttendance.filter(function (r) { return r.status === "On-leave"; }).length;
    const absent = todayAttendance.filter(function (r) { return r.status === "Absent"; }).length;
    const totalStudents = (database.students || []).filter(function (s) { return String(s.status || "active").toLowerCase() !== "inactive"; }).length;
    const totalAttendance = Math.max(todayAttendance.length, present + leave + absent);
    const unmarked = Math.max(0, totalStudents - totalAttendance);
    const attRows = [
      { label: "Present", value: present },
      { label: "On-leave", value: leave },
      { label: "Absent", value: absent },
      { label: "Unmarked", value: unmarked }
    ];
    el.innerHTML = (totalAttendance || unmarked)
      ? buildDashboardBars(attRows, Math.max.apply(null, attRows.map(function (r) { return r.value; })))
      : '<p class="empty-state">No students found for attendance overview.</p>';
    renderDashboardTodayAttendance();
  }

  function updateDashboardClock() {
    const clockEl = document.getElementById("heroLiveClock");
    const dateEl = document.getElementById("heroLiveDate");
    if (!clockEl || !dateEl) {
      return;
    }
    const now = new Date();
    clockEl.textContent = now.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit", second: "2-digit" });
    dateEl.textContent = now.toLocaleDateString([], { weekday: "short", year: "numeric", month: "short", day: "2-digit" });
  }

  function startDashboardClock() {
    updateDashboardClock();
    if (!dashboardClockTimer) {
      dashboardClockTimer = setInterval(updateDashboardClock, 1000);
    }
  }

  function renderDashboardTodayAttendance() {
    var absentContainer = document.getElementById("dashboardAbsentStudents");
    var presentContainer = document.getElementById("dashboardPresentEmployees");
    if (!absentContainer || !presentContainer) return;

    var todayISO = getTodayDateISO();
    var attendanceData = database.attendance || [];
    var students = database.students || [];
    var teachers = database.teachers || [];
    var classes = database.classes || [];

    // Absent students today
    var absentRecords = attendanceData.filter(function (a) {
      var isStudent = !a.entityType || a.entityType === "student";
      return isStudent && a.date === todayISO && String(a.status).toLowerCase() === "absent";
    });

    if (absentRecords.length === 0) {
      absentContainer.innerHTML = '<p class="empty-state" style="padding:1rem;">No absent students today.</p>';
    } else {
      var absentHTML = "";
      var shownIds = {};
      var absCount = 0;
      absentRecords.forEach(function (rec) {
        if (shownIds[rec.studentId]) return;
        if (absCount >= 5) return;
        shownIds[rec.studentId] = true;
        absCount++;
        var student = students.find(function (s) { return s.id === rec.studentId; });
        if (!student) return;
        var initials = (student.name || "?").split(" ").map(function (w) { return (w[0] || "").toUpperCase(); }).slice(0, 2).join("");
        absentHTML += '<div class="dashboard-attendance-item">';
        if (student.picture) {
          absentHTML += '<img src="' + escapeAttr(student.picture) + '" alt="" class="dashboard-attendance-item__avatar">';
        } else {
          absentHTML += '<span class="dashboard-attendance-item__avatar dashboard-attendance-item__avatar--initials">' + initials + '</span>';
        }
        absentHTML += '<div class="dashboard-attendance-item__info">';
        absentHTML += '<p class="dashboard-attendance-item__roll">' + escapeHtml(student.admissionNo || "-") + '</p>';
        absentHTML += '<p class="dashboard-attendance-item__name">' + escapeHtml(student.name || "-") + '</p>';
        absentHTML += '<p class="dashboard-attendance-item__class">' + escapeHtml(student.className || "-") + '</p>';
        absentHTML += '</div></div>';
      });
      absentContainer.innerHTML = (absentHTML || '<p class="empty-state" style="padding:1rem;">No absent students today.</p>');
      var sendBtn = document.getElementById("dashboardSendAbsenteesBtnOld");
      if (!sendBtn) {
        var btnWrap = document.createElement("div");
        btnWrap.style.cssText = "margin-top:0.6rem;text-align:center;";
        btnWrap.innerHTML = '<button id="dashboardSendAbsenteesBtnOld" type="button" style="display:inline-flex;align-items:center;gap:0.3rem;padding:0.3rem 0.8rem;font-size:0.75rem;font-family:inherit;font-weight:600;color:#fff;background:#e74c3c;border:none;border-radius:8px;cursor:pointer;line-height:1.4;"><i class="fas fa-paper-plane"></i> Send Absentees Message</button>';
        absentContainer.appendChild(btnWrap);
        safeOn(document.getElementById("dashboardSendAbsenteesBtnOld"), "click", async function () {
          try {
            var todayAttendance = database.attendance || [];
            var absentStudents = [];
            var seenIds = {};
            todayAttendance.forEach(function (a) {
              var isStudent = !a.entityType || a.entityType === "student";
              if (isStudent && a.date === todayISO && String(a.status).toLowerCase() === "absent" && !seenIds[a.studentId]) {
                seenIds[a.studentId] = true;
                var s = students.find(function (st) { return st.id === a.studentId; });
                if (s) absentStudents.push(s);
              }
            });
            if (!absentStudents.length) {
              openAppMessageBox("Warning", "No absent students found for today.", "warning");
              return;
            }
            var _dacfg = getSupabaseConfig();
            var _daqOk = _dacfg && _dacfg.url && _dacfg.anonKey && _dacfg.tablesCreated && window.supabase ? true : false;
            if (!_daqOk && !(database.generalSettings && database.generalSettings.smsGateway && database.generalSettings.smsGateway.connected)) {
              openAppMessageBox("Error", "SMS gateway is not connected. Please connect from SMS Services first or configure Cloud Queue.", "error");
              return;
            }
            var success = 0, failed = 0, noPhone = 0;
            for (var i = 0; i < absentStudents.length; i++) {
              var st = absentStudents[i];
              var normSt = normalizeStudentForPrint(st);
              var phone = normalizeSmsPhone(normSt.phone || normSt.fatherPhone || "");
              if (!phone) { noPhone++; failed++; continue; }
              var template = buildCommunicationTemplate("student-absent", {
                prefix: getGenderPrefix(normSt.gender),
                name: normSt.name || "-",
                rollNo: normSt.admissionNo || "-",
                date: todayISO
              });
              var text = interpolateTemplate(template, {
                name: normSt.name || "-",
                roll: normSt.admissionNo || "-",
                prefix: getGenderPrefix(normSt.gender),
                class: normSt.className || "-",
                date: todayISO,
                school: (database.school || {}).name || "School"
              });
              var result = await sendSmsSmart({
                recipientName: normSt.name || "-",
                recipientPhone: phone,
                message: text,
                source: "Dashboard Absentees SMS",
                recipientType: "student",
                campaignType: "absentees"
              });
              if (result.success) success++; else failed++;
            }
            var detail = "SMS alert processed. Success: " + success + ", Failed: " + failed + (noPhone ? ", Missing Phone: " + noPhone : "") + ".";
            openAppMessageBox(failed ? "Warning" : "Success", detail, failed ? "warning" : "success");
          } catch (e) {
            console.error("Send Absentees Error:", e);
            openAppMessageBox("Error", String(e && e.message ? e.message : e), "error");
          }
        });
      }
    }

    // Present employees today
    var presentRecords = attendanceData.filter(function (a) {
      return a.entityType === "employee" && a.date === todayISO && String(a.status).toLowerCase() === "present";
    });

    if (presentRecords.length === 0) {
      presentContainer.innerHTML = '<p class="empty-state" style="padding:1rem;">No employees present yet today.</p>';
    } else {
      var presentHTML = "";
      var shownEmpIds = {};
      var empCount = 0;
      presentRecords.forEach(function (rec) {
        if (shownEmpIds[rec.employeeId]) return;
        if (empCount >= 5) return;
        shownEmpIds[rec.employeeId] = true;
        empCount++;
        var emp = teachers.find(function (e) { return e.id === rec.employeeId; });
        if (!emp) return;
        var empClass = classes.find(function (c) { return String(c.teacher || "").toLowerCase() === String(emp.name || "").toLowerCase(); });
        var initials = (emp.name || "?").split(" ").map(function (w) { return (w[0] || "").toUpperCase(); }).slice(0, 2).join("");
        presentHTML += '<div class="dashboard-attendance-item">';
        if (emp.picture) {
          presentHTML += '<img src="' + escapeAttr(emp.picture) + '" alt="" class="dashboard-attendance-item__avatar">';
        } else {
          presentHTML += '<span class="dashboard-attendance-item__avatar dashboard-attendance-item__avatar--initials">' + initials + '</span>';
        }
        presentHTML += '<div class="dashboard-attendance-item__info">';
        presentHTML += '<p class="dashboard-attendance-item__roll">' + escapeHtml(emp.id || "-") + '</p>';
        presentHTML += '<p class="dashboard-attendance-item__name">' + escapeHtml(emp.name || "-") + '</p>';
        presentHTML += '<p class="dashboard-attendance-item__class">' + escapeHtml(empClass ? empClass.name : "-") + '</p>';
        presentHTML += '</div></div>';
      });
      presentContainer.innerHTML = presentHTML || '<p class="empty-state" style="padding:1rem;">No employees present yet today.</p>';
    }
  }

  function getParentChildren() {
    var parentPhone = String(currentUser.phone || "").trim();
    if (!parentPhone) return [];
    var normalized = parentPhone.replace(/[\s\-]/g, "").toLowerCase();
    return (database.students || []).filter(function (s) {
      var fp = String(s.fatherPhone || "").replace(/[\s\-]/g, "").toLowerCase();
      var mp = String(s.motherPhone || "").replace(/[\s\-]/g, "").toLowerCase();
      return fp === normalized || mp === normalized;
    });
  }

  function renderParentDashboard() {
    var children = getParentChildren();
    var container = document.getElementById("moduleSummary");
    if (!container) return;
    if (!children.length) {
      container.innerHTML = '<article class="panel-card"><div class="panel-card__header"><div><p class="panel-label">My Children</p><h3>No children found</h3></div></div><div class="panel-card__body"><p class="helper-text">No student records are linked to your account.</p></div></article>';
      return;
    }
    container.innerHTML = '<article class="panel-card"><div class="panel-card__header"><div><p class="panel-label">My Children</p><h3>' + children.length + ' child' + (children.length > 1 ? "ren" : "") + ' enrolled</h3></div></div><div class="panel-card__body"><div class="stacked-copy" style="display:grid;gap:0.75rem;">' +
      children.map(function (child) {
        var genderLabel = child.gender === "male" ? "Son" : "Daughter";
        return '<div class="compact-list" style="border:1px solid var(--border-color);border-radius:12px;padding:0.75rem;background:#fff;">' +
          '<div style="display:flex;align-items:center;gap:0.75rem;margin-bottom:0.5rem;">' +
          '<div class="profile-avatar" style="width:44px;height:44px;border-radius:50%;background:#1e5eff;color:#fff;display:flex;align-items:center;justify-content:center;font-weight:700;font-size:1rem;">' + getInitials(child.name) + '</div>' +
          '<div><strong style="font-size:1rem;">' + escapeHtml(child.name) + '</strong><br><span style="font-size:0.82rem;color:var(--text-muted);">' + escapeHtml(child.className || "") + " | Roll: " + escapeHtml(child.admissionNo || "") + '</span></div>' +
          '</div>' +
          '<div style="display:flex;gap:0.4rem;flex-wrap:wrap;">' +
          '<button type="button" class="table-action-btn" data-parent-view="attendance" data-student-id="' + escapeAttr(child.id) + '">Attendance</button>' +
          '<button type="button" class="table-action-btn" data-parent-view="fees" data-student-id="' + escapeAttr(child.id) + '">Fees</button>' +
          '<button type="button" class="table-action-btn" data-parent-view="report" data-student-id="' + escapeAttr(child.id) + '">Report Card</button>' +
          '<button type="button" class="table-action-btn" data-parent-view="details" data-student-id="' + escapeAttr(child.id) + '">Details</button>' +
          '</div></div>';
      }).join("") +
      '</div></div></article>';
    container.querySelectorAll("[data-parent-view]").forEach(function (btn) {
      btn.addEventListener("click", function () {
        var action = btn.getAttribute("data-parent-view");
        var studentId = btn.getAttribute("data-student-id");
        var student = database.students.find(function (s) { return s.id === studentId; });
        if (!student) return;
        if (action === "attendance") openStudentModal(student, "attendance");
        else if (action === "fees") openStudentModal(student, "fees");
        else if (action === "report") openStudentModal(student, "report");
        else if (action === "details") openStudentModal(student);
      });
    });
  }

  function renderDashboard() {
    if (activeRoute && activeRoute !== "dashboard" && activeRoute !== "home") return;
    try { refreshDatabase(); } catch (_e) { console.error("[DASH] refreshDatabase:", _e.message); }
    try { applySavedThemeSettings(); } catch (_e) { console.error("[DASH] applySavedThemeSettings:", _e.message); }
    if (currentUser.role === "parent") {
      try { renderParentDashboard(); } catch (_e) { console.error("[DASH] renderParentDashboard:", _e.message); }
      try { applyMessagingVisibility(); } catch (_e) {}
      return;
    }
    try { renderStats(); } catch (_e) { console.error("[DASH] renderStats:", _e.message); }
    try { renderActivity(); } catch (_e) {}
    try { renderInsights(); } catch (_e) {}
    try { renderDashboardMiniCards(); } catch (_e) {}
    try { renderDashboardAnalytics(); } catch (_e) { console.error("[DASH] renderDashboardAnalytics:", _e.message); }
    try { refreshAttendanceOverview(); } catch (_e) {}
    try { renderDashboardTodayAttendance(); } catch (_e) {}
    try { startDashboardClock(); } catch (_e) {}
    try { updateHero(); } catch (_e) {}
    try { renderStudentsWorkspace(); } catch (_e) {}
    try { applyMessagingVisibility(); } catch (_e) {}
    if (window.applyLanguage && database.generalSettings && database.generalSettings.themeLanguage && database.generalSettings.themeLanguage.language) {
      try { window.applyLanguage(database.generalSettings.themeLanguage.language); } catch (_e) {}
    }
    setTimeout(setupRevealAnimations, 80);
  }

  function generateStudentId() {
    return `STU-${generateId()}`;
  }

  function createStudentLogin(student) {
    const email = `${student.admissionNo.toLowerCase()}@student.local`;
    const password = `${student.admissionNo.toLowerCase()}123`;
    const existingUserIndex = database.users.findIndex(function (user) {
      return user.role === "student" && user.id === `LOGIN-${student.id}`;
    });

    const loginUser = {
      id: `LOGIN-${student.id}`,
      name: student.name,
      email: email,
      password: password,
      role: "student",
      phone: student.phone,
      active: student.status === "active"
    };

    if (existingUserIndex >= 0) {
      database.users[existingUserIndex] = loginUser;
      addActivity("Student login updated", `${student.name} login credentials were refreshed.`);
    } else {
      database.users.push(loginUser);
      addActivity("Student login created", `${student.name} received a new student login.`);
    }

    saveDatabase("Saving student login...", [{ table: "app_users", record: loginUser, operation: existingUserIndex >= 0 ? "update" : "create" }]);
    refreshDatabase();
    renderDashboard();
    setStudentRoute("students-manage-login");
  }

  function createParentLogin(student) {
    var loginId = getParentLoginId(student);
    var parentPhone = student.fatherPhone || student.motherPhone || "";
    var normalizedPhone = parentPhone.replace(/[\s-]/g, "").toLowerCase();
    var email, password;
    if (normalizedPhone) {
      email = normalizedPhone + "@parent.local";
      password = "parent" + normalizedPhone.replace(/[^0-9]/g, "").slice(-4);
    } else {
      email = "parent." + student.id + "@parent.local";
      password = "parent" + (student.id.replace(/[^0-9]/g, "").slice(-4) || "1234");
    }
    var existingUserIndex = database.users.findIndex(function (user) {
      return user.role === "parent" && user.id === loginId;
    });
    var loginUser = {
      id: loginId,
      name: student.fatherName || student.motherName || student.name + "'s Parent",
      email: email,
      password: password,
      role: "parent",
      phone: parentPhone,
      active: true
    };
    if (existingUserIndex >= 0) {
      database.users[existingUserIndex] = loginUser;
      addActivity("Parent login updated", `${loginUser.name} login credentials were refreshed.`);
    } else {
      database.users.push(loginUser);
      addActivity("Parent login created", `${loginUser.name} received a new parent login.`);
    }
    saveDatabase("Saving parent login...", [{ table: "app_users", record: loginUser, operation: existingUserIndex >= 0 ? "update" : "create" }]);
    refreshDatabase();
    renderDashboard();
    setStudentRoute("parents-manage-login");
  }

  async function handleStudentFormSubmit(event) {
    event.preventDefault();

    let pictureData = currentStudentPicture;

    try {
      pictureData = await readStudentPicture(studentPictureInput.files[0]);
    } catch (error) {
      setFormMessage(error.message, "error");
      return;
    }

    const studentId = studentIdInput.value;
    const admissionNumber = admissionNoInput.value.trim();
    var _selectedDiscountTypeId = discountTypeSelectInput ? discountTypeSelectInput.value : "";
    var _settings = database.generalSettings || {};
    var _selectedDt = (_selectedDiscountTypeId && (_settings.discountTypes || []).find(function (d) { return d.id === _selectedDiscountTypeId; })) || null;
    const studentRecord = {
      id: studentId || generateStudentId(),
      admissionNo: "STD" + admissionNumber,
      name: studentNameInput.value.trim(),
      picture: pictureData,
      dateOfAdmission: dateOfAdmissionInput.value,
      className: studentClassNameInput.value,
      discountInFee: _selectedDt ? String(_selectedDt.percentage) : "",
      discountTypeId: _selectedDt ? _selectedDt.id : "",
      discountType: _selectedDt ? _selectedDt.name : "",
      discountAmount: 0,
      dateOfBirth: dateOfBirthInput.value,
      gender: studentGenderInput.value,
      bloodGroup: bloodGroupInput.value.trim(),
      diseaseInfo: diseaseInfoInput.value.trim(),
      birthId: birthIdInput.value.trim(),
      previousSchool: previousSchoolInput.value.trim(),
      previousId: previousIdInput.value.trim(),
      orphanStatus: orphanStatusInput.value,
      religion: religionInput.value.trim(),
      address: studentAddressInput.value.trim(),
      phone: studentPhoneInput.value.trim(),
      fatherName: fatherNameInput.value.trim(),
      fatherEducation: fatherEducationInput.value.trim(),
      fatherNationalId: fatherNationalIdInput.value.trim(),
      fatherPhone: fatherPhoneInput.value.trim(),
      fatherOccupation: fatherOccupationInput.value.trim(),
      fatherIncome: fatherIncomeInput.value.trim(),
      motherName: motherNameInput.value.trim(),
      motherEducation: motherEducationInput.value.trim(),
      motherNationalId: motherNationalIdInput.value.trim(),
      motherPhone: motherPhoneInput.value.trim(),
      motherOccupation: motherOccupationInput.value.trim(),
      status: studentStatusInput.value
    };

    if (!studentRecord.name || !studentRecord.dateOfAdmission || !studentRecord.className) {
      setFormMessage("Please fill Student Name, Date of Admission, and Select Class.", "error");
      return;
    }

    const duplicateAdmission = database.students.find(function (student) {
      return student.admissionNo.toLowerCase() === studentRecord.admissionNo.toLowerCase() && student.id !== studentRecord.id;
    });

    if (duplicateAdmission) {
      setFormMessage("Admission number already exists. Use a unique value.", "error");
      return;
    }

    const existingIndex = database.students.findIndex(function (student) {
      return student.id === studentRecord.id;
    });

    var _studentChanges = [{ table: "students", record: studentRecord, operation: existingIndex >= 0 ? "update" : "create" }];

    if (existingIndex >= 0) {
      database.students[existingIndex] = studentRecord;
      const loginIndex = database.users.findIndex(function (user) {
        return user.role === "student" && user.id === `LOGIN-${studentRecord.id}`;
      });
      if (loginIndex >= 0) {
        database.users[loginIndex].active = studentRecord.status === "active";
      }
      addActivity("Student updated", `${studentRecord.name} record was updated.`);
      setFormMessage("Student updated successfully.", "success");
    } else {
      database.students.unshift(studentRecord);
      addActivity("Student added", `${studentRecord.name} was added to the student directory.`);
      setFormMessage("Student added successfully.", "success");
    }

    if (studentRecord.fatherPhone || studentRecord.motherPhone) {
      var parentPhone = studentRecord.fatherPhone || studentRecord.motherPhone || "";
      var normalizedPhone = parentPhone.replace(/[\s-]/g, "").toLowerCase();
      var existingParentIndex = database.users.findIndex(function (u) {
        return u.role === "parent" && u.id === "PARENT-" + normalizedPhone;
      });
      if (existingParentIndex < 0) {
        var _newParent = {
          id: "PARENT-" + normalizedPhone,
          name: studentRecord.fatherName || studentRecord.motherName || studentRecord.name + "'s Parent",
          email: normalizedPhone + "@parent.local",
          password: "parent" + normalizedPhone.replace(/[^0-9]/g, "").slice(-4),
          role: "parent",
          phone: parentPhone,
          active: true
        };
        database.users.push(_newParent);
        _studentChanges.push({ table: "app_users", record: _newParent, operation: "create" });
      }
    }

    await saveDatabase(existingIndex >= 0 ? "Updating student..." : "Saving student...", _studentChanges);
    populateStudentForm(null);
    setStudentRoute("all-students");
  }

  function handleTableActionClick(event) {
    const actionButton = event.target.closest("[data-action]");

    if (!actionButton) {
      return;
    }

    const action = actionButton.dataset.action;
    const studentId = actionButton.dataset.id;
    const student = database.students.find(function (item) { return item.id === studentId; });


    if (!student && action !== "create-student-login" && action !== "create-parent-login" && action !== "toggle-promote-selection" && action !== "edit-parent-login" && action !== "save-parent-login") {
      return;
    }

    if (action === "edit-student") {
      setStudentRoute("students-add-new", { preserveForm: true });
      populateStudentForm(student);
      return;
    }

    if (action === "view-student") {
      const student = database.students.find(function (item) { return item.id === studentId; });
      if (student) {
        openStudentModal(student);
      }
      return;
    }

    if (action === "send-student-whatsapp") {
      sendDirectWhatsappToStudent(student, student.name || "student");
      return;
    }

    if (action === "print-student-id-card") {
      printSingleStudentIdCard(student);
      return;
    }

    if (action === "sms-student-id-card") {
      sendStudentIdCardSms(student);
      return;
    }

    if (action === "whatsapp-student-id-card") {
      sendStudentIdCardWhatsapp(student);
      return;
    }

    if (action === "toggle-student-status") {
      student.status = student.status === "active" ? "inactive" : "active";
      addActivity("Student status changed", `${student.name} is now ${student.status}.`);
      saveDatabase("Toggling student status...", [{ table: "students", record: student, operation: "update" }]);
      renderDashboard();
      setStudentRoute("students-active-inactive");
      return;
    }

    if (action === "delete-student") {
      const student = database.students.find(function (item) { return item.id === studentId; });
      if (student) {
        showStyledDeleteConfirmation(student.name, function() {
          trackDeletion(student.id);
          var _removedUser = database.users.find(function (user) {
            return user.id === `LOGIN-${student.id}`;
          });
          database.students = database.students.filter(function (item) {
            return item.id !== student.id;
          });
          database.users = database.users.filter(function (user) {
            return user.id !== `LOGIN-${student.id}`;
          });
          addActivity("Student deleted", `${student.name} record was removed.`);
          saveDatabase("Deleting student...", [
            { table: "students", record: student, operation: "delete" },
            { table: "app_users", record: _removedUser, operation: "delete" }
          ]);
          renderDashboard();
          setStudentRoute("all-students");
        });
      }
      return;
    }

    if (action === "create-student-login") {
      const loginStudent = database.students.find(function (item) { return item.id === studentId; });
      if (loginStudent) {
        createStudentLogin(loginStudent);
      }
    }

    if (action === "create-parent-login") {
      const parentStudent = database.students.find(function (item) { return item.id === studentId; });
      if (parentStudent) {
        createParentLogin(parentStudent);
      }
    }

    if (action === "edit-parent-login") {
      var tr = actionButton.closest("tr");
      if (tr) {
        var inputs = tr.querySelectorAll(".parent-login-cred-input");
        inputs.forEach(function (inp) { inp.disabled = false; });
        var toggle = tr.querySelector(".parent-login-toggle");
        if (toggle) toggle.disabled = false;
        actionButton.style.display = "none";
        var saveBtn = tr.querySelector('[data-action="save-parent-login"]');
        if (saveBtn) saveBtn.style.display = "";
      }
      return;
    }

    if (action === "save-parent-login") {
      saveParentLoginCredentials(studentId);
      return;
    }

    if (action === "save-student-login") {
      saveStudentLoginCredentials(studentId);
      return;
    }

    if (action === "toggle-promote-selection") {
      const checkbox = actionButton;
      promoteSelectionState[studentId] = checkbox.checked;
    }
  }

  function handleAllClassesTableClick(event) {
    const actionButton = event.target.closest("[data-action]");

    if (!actionButton) {
      return;
    }

    const action = actionButton.dataset.action;
    const classId = actionButton.dataset.id;
    const classItem = database.classes.find(function (item) {
      return item.id === classId;
    });

    if (!classItem) {
      return;
    }

    if (action === "class-view-boys") {
      allStudentsClassFilter.value = classItem.name;
      allStudentsGenderFilter.value = "Male";
      setRoute("all-students");
      return;
    }

    if (action === "class-view-girls") {
      allStudentsClassFilter.value = classItem.name;
      allStudentsGenderFilter.value = "Female";
      setRoute("all-students");
      return;
    }

    if (action === "edit-class") {
      setRoute("new-class");
      populateClassForm(classItem);
      return;
    }

    if (action === "delete-class") {
      const hasStudents = database.students.some(function (student) {
        return student.className === classItem.name;
      });

      if (hasStudents) {
        setAllClassesMessage("This class has enrolled students. Move students first, then delete class.", "error");
        return;
      }

      showStyledDeleteConfirmation(classItem.name, function() {
        trackDeletion(classId);
        const deletedClassName = String(classItem.name || "").trim();
        var _removedSubjects = (database.subjects || []).filter(function (subject) {
          return String(subject.className || "").trim() === deletedClassName;
        });
        database.classes = database.classes.filter(function (item) {
          return item.id !== classId;
        });
        database.subjects = (database.subjects || []).filter(function (subject) {
          return String(subject.className || "").trim() !== deletedClassName;
        });
        if (database.classSubjects && typeof database.classSubjects === "object") {
          delete database.classSubjects[deletedClassName];
        }
        if (assignSubjectsClassInput && String(assignSubjectsClassInput.value || "").trim() === deletedClassName) {
          assignSubjectsClassInput.value = "";
          populateAssignSubjectsForm("");
        }
        addActivity("Class deleted", `${classItem.name} was deleted.`);
        var _classChanges = [{ table: "classes", record: classItem, operation: "delete" }];
        _removedSubjects.forEach(function (sub) { _classChanges.push({ table: "subjects", record: sub, operation: "delete" }); });
        saveDatabase("Deleting class...", _classChanges);
        refreshDatabase();
        renderDashboard();
        setStudentRoute("all-classes");
        setAllClassesMessage("Class deleted successfully.", "success");
      });
    }
  }

  function toggleAccordion(button) {
    const group = button.closest(".menu-group");
    const isOpen = group.classList.contains("open");

    document.querySelectorAll(".menu-group").forEach(function (menuGroup) {
      menuGroup.classList.remove("open");
      const trigger = menuGroup.querySelector(".menu-group__trigger");
      if (trigger) {
        trigger.setAttribute("aria-expanded", "false");
      }
    });

    if (!isOpen) {
      group.classList.add("open");
      button.setAttribute("aria-expanded", "true");
    }
  }

  function applySidebarState() {
    const isCollapsed = Boolean(database.settings.sidebarCollapsed);
    appShell.classList.toggle("sidebar-collapsed", isCollapsed);
    sidebar.classList.toggle("is-collapsed", isCollapsed);
  }

  function scrollContentToTop() {
    const contentArea = document.querySelector(".content-area");
    if (contentArea) {
      contentArea.scrollTop = 0;
    }
    window.scrollTo(0, 0);
  }

  function setupRevealAnimations() {
    if (window._revealObserver) {
      window._revealObserver.disconnect();
    }
    var targets = document.querySelectorAll(".stats-grid > *, .dashboard-grid > *");
    if (!targets.length) return;
    var viewportH = window.innerHeight || document.documentElement.clientHeight;
    targets.forEach(function (el) {
      var rect = el.getBoundingClientRect();
      if (rect.top < viewportH - 40) {
        el.classList.add("reveal-visible");
      }
    });
    var observer = new IntersectionObserver(function (entries) {
      entries.forEach(function (entry) {
        if (entry.isIntersecting) {
          entry.target.classList.add("reveal-visible");
          observer.unobserve(entry.target);
        }
      });
    }, { threshold: 0.05, rootMargin: "0px 0px -20px 0px" });
    targets.forEach(function (el) {
      if (!el.classList.contains("reveal-visible")) {
        observer.observe(el);
      }
    });
    window._revealObserver = observer;
  }

  function setRoute(route) {
    const normalizedRoute = route === "settings" ? "account-settings" : route;
    if (!isRouteAllowedByRole(normalizedRoute)) {
      openAppMessageBox("Error", "This option is not allowed for your role.", "error");
      return;
    }
    if (isRouteLockedByLicense(normalizedRoute)) {
      openAppMessageBox("Error", getLicenseLockState().reason, "error");
      return;
    }
    const title = routeTitles[normalizedRoute] || "Module Workspace";
    activeRoute = normalizedRoute;
    const isDashboard = normalizedRoute === "dashboard";
    const isStudentsModule = studentRoutes.includes(normalizedRoute) || classRoutes.includes(normalizedRoute);

    views.forEach(function (view) {
      const shouldShow =
        (isDashboard && view.dataset.view === "dashboard") ||
        (isStudentsModule && view.dataset.view === "students-workspace") ||
        (!isDashboard && !isStudentsModule && view.dataset.view === "module");

      view.classList.toggle("active", shouldShow);
    });

    routeButtons.forEach(function (button) {
      button.classList.toggle("active", button.dataset.route === normalizedRoute);
    });

    document.querySelectorAll(".menu-group").forEach(function (menuGroup) {
      menuGroup.classList.remove("open");
      var trigger = menuGroup.querySelector(".menu-group__trigger");
      if (trigger) { trigger.setAttribute("aria-expanded", "false"); }
    });
    var _activeBtn = sidebar.querySelector('.menu-link[data-route="' + normalizedRoute + '"], .submenu-link[data-route="' + normalizedRoute + '"]');
    if (_activeBtn) {
      var _parentGroup = _activeBtn.closest(".menu-group");
      if (_parentGroup) {
        _parentGroup.classList.add("open");
        var _trigger = _parentGroup.querySelector(".menu-group__trigger");
        if (_trigger) { _trigger.setAttribute("aria-expanded", "true"); }
      }
    }

    pageTitle.textContent = title;
    scrollContentToTop();
    profileMenu.classList.remove("open");
    const settingsSubmenu = document.getElementById("settingsSubmenu");
    if (settingsSubmenu) {
      settingsSubmenu.hidden = true;
    }
    if (notificationMenu) {
      notificationMenu.classList.remove("open");
    }
    appShell.classList.remove("sidebar-open");

    if (isStudentsModule) {
      setStudentRoute(normalizedRoute);
      setTimeout(scheduleMobileFix, 100);
      return;
    }

    if (isDashboard) {
      renderDashboard();
      setTimeout(setupRevealAnimations, 50);
      scheduleMobileFix();
      return;
    }

    renderDynamicModuleWorkspace(normalizedRoute, title);
    var _guide = document.getElementById("moduleGuide");
    var _summary = document.getElementById("moduleSummary");
    if (_guide && _summary && _guide.innerHTML.trim()) {
      var _div = document.createElement("div");
      _div.style.cssText = "margin-top:16px;padding:12px;border:1px solid #dde4ea;border-radius:8px;";
      while (_guide.firstChild) {
        _div.appendChild(_guide.firstChild);
      }
      _summary.appendChild(_div);
      var _panel = _guide.closest(".panel-card");
      if (_panel) { _panel.style.display = "none"; }
      var _leftPanel = _summary.closest(".panel-card");
      if (_leftPanel) { _leftPanel.style.gridColumn = "1 / -1"; }
    }
    setTimeout(setupRevealAnimations, 50);
    applyMessagingVisibility();
    setTimeout(function() { applySavedThemeSettings(); }, 30);
    scheduleMobileFix();
  }

