  (function initDarkMode() {
    var saved = localStorage.getItem("sagarsoft-theme");
    if (saved === "dark") { document.body.setAttribute("data-theme", "dark"); }
    var btn = document.getElementById("themeToggleBtn");
    var icon = document.getElementById("themeToggleIcon");
    if (btn) {
      btn.addEventListener("click", function () {
        var isDark = document.body.getAttribute("data-theme") === "dark";
        if (isDark) {
          document.body.removeAttribute("data-theme");
          localStorage.setItem("sagarsoft-theme", "light");
          if (icon) { icon.className = "fas fa-moon"; }
        } else {
          document.body.setAttribute("data-theme", "dark");
          localStorage.setItem("sagarsoft-theme", "dark");
          if (icon) { icon.className = "fas fa-sun"; }
        }
      });
    }
    if (icon) { icon.className = saved === "dark" ? "fas fa-sun" : "fas fa-moon"; }
  })();

  var _serverLoadAuthFailed = false;
  (async function loadFromServerAfterInit() {
    var license = database.generalSettings && database.generalSettings.licenseSettings;
    var wasActivated = license && license.activated;
    var schoolId = "";
    var authToken = license && license.licenseToken;
    if (window.SagarSoftDB && window.SagarSoftDB.getConfig) {
      var cfg = window.SagarSoftDB.getConfig();
      if (cfg && cfg.schoolId) schoolId = String(cfg.schoolId).trim();
      if (cfg && cfg.authToken) authToken = authToken || cfg.authToken;
    }
    if (!schoolId && license && license.schoolId) {
      schoolId = String(license.schoolId).trim();
    }
    if (schoolId && window.SagarSoftDB && window.SagarSoftDB.setSchoolId) {
      window.SagarSoftDB.setSchoolId(schoolId);
      try {
        var serverDb = await window.SagarSoftDB.loadDatabaseFromServer();
        if (serverDb) {
          database = serverDb;
          ensureLicenseSettings();
          var _lsBefore = database.generalSettings.licenseSettings || {};
          if (wasActivated || (currentUser && currentUser.serverToken)) {
            database.generalSettings.licenseSettings.activated = true;
            database.generalSettings.licenseSettings.status = "active";
          }
          var _lsAfter = database.generalSettings.licenseSettings || {};
          if (!_lsAfter.activated && _lsAfter.expiryDate) {
            var _expAfter = new Date(_lsAfter.expiryDate);
            if (!isNaN(_expAfter.getTime()) && _expAfter > new Date()) {
              _lsAfter.activated = true;
              if (!_lsAfter.status || _lsAfter.status === "inactive") _lsAfter.status = "active";
            }
          }
          database.generalSettings.licenseSettings.schoolId = schoolId;
          normalizeStudentsDatasetInMemory();
          isolateSuperAdminData();
          applyRouteAccessVisibility();
          if (typeof renderDashboard === "function") renderDashboard();
        }
      } catch (_e) {
        console.error("[LOAD-SERVER] Error loading from server:", _e.message);
        var _statusCode = _e.statusCode || 0;
        if (_statusCode === 401 || _statusCode === 403 || (_e.message && (_e.message.indexOf("401") > -1 || _e.message.indexOf("Invalid school token") > -1 || _e.message.indexOf("School authentication required") > -1))) {
          _serverLoadAuthFailed = true;
        }
      }
    }
  })();

